const LanguageContext = createContext<{ 
  language: Language; 
  toggleLanguage: () => void;
  setLanguage: (lang: Language) => void;
}>({
  language: "id",
  toggleLanguage: () => {},
  setLanguage: () => {},
});

export function LanguageProvider({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();
  const router = useRouter();
  const language: Language = pathname === "/en" || pathname.startsWith("/en/") ? "en" : "id";

  useEffect(() => {
    document.documentElement.lang = language;
  }, [language]);

  const setLanguage = (target: Language) => {
    if (target === language) return;
    router.push(localizeHref(pathname, target));
  };

  const toggleLanguage = () => {
    const nextLanguage = language === "id" ? "en" : "id";
    setLanguage(nextLanguage);
  };

  return (
    <LanguageContext.Provider value={{ language, toggleLanguage, setLanguage }}>
      {children}
    </LanguageContext.Provider>
  );
}

export function useLanguage() {
  return useContext(LanguageContext);
}

export function localize(text: string, language: Language) {
  return language === "en" ? translations[text] ?? text : text;
}

const englishPaths: Record<string, string> = {
  "/": "/en",
  "/layanan": "/en/services",
  "/portofolio": "/en/portfolio",
  "/tentang-kami": "/en/about",
  "/kontak": "/en/contact",
};

const indonesianPaths: Record<string, string> = Object.fromEntries(
  Object.entries(englishPaths).map(([indonesianPath, englishPath]) => [englishPath, indonesianPath]),
);

export function localizeHref(href: string, language: Language) {
  const paths = language === "en" ? englishPaths : indonesianPaths;
  return paths[href] ?? href;
}
